    content: `
## حيث يلتقي التراث العالمي بالشاشة الكبيرة

للمغرب تسعة مواقع تراث عالمي مسجَّلة لدى اليونسكو، وعدد لافت منها كان بمثابة مواقع تصوير لبعض أضخم الإنتاجات في تاريخ السينما. والسبب بسيط: هذه أماكن لم تتغيّر فيها العمارة والضوء والمشهد الطبيعي إلا قليلًا على مدى قرون. فالمخرج الباحث عن روما القديمة، أو القدس التوراتية، أو مدينة شرقية خيالية، لا يحتاج إلى بنائها — ففي المغرب هي قائمة أصلًا.

يمرّ هذا الدليل على مواقع اليونسكو التي دارت فيها الكاميرات فعلًا، وما صُوِّر فيها، و — لأن بإمكانك زيارتها جميعًا — كيف تقف في المكان نفسه الذي صُوِّر فيه المشهد.

## آيت بن حدو: المكان الأكثر تصويرًا في إفريقيا

إن كان للمغرب عاصمة سينمائية، فهي **قصر آيت بن حدو** — مجموعة من القصبات الطينية ترتفع في وادي أونيلا، سجّلتها اليونسكو عام **1987**. إنه المكان الأكثر تصويرًا في القارة الإفريقية، وقد ظهر في أكثر من ثمانين إنتاجًا على مدى ستة عقود.

تُقرأ القائمة كمنهج في دراسات السينما. استخدم **لورنس العرب** (1962) أسواره؛ وتبعه **جوهرة النيل** (1985) و**المومياء** (1999). ثم جاء فيلم **المصارع** (2000) لريدلي سكوت، الذي صُوِّرت مشاهد سوق العبيد ومدرسة المصارعين فيه عند سفح القصبة — الفيلم الذي أعاد آيت بن حدو إلى خريطة هوليوود. وتلاه **الإسكندر** (2004) و**مملكة السماء** (2005) و**أمير بلاد فارس** (2010). وبالنسبة لجيل جديد فهو **يونكاي**، مدينة العبيد التي تفتحها دينيريس تارغيريان في الموسمين الثالث والرابع من **صراع العروش**.

والأهم أن لا شيء من هذا ديكور. إنها قرية يونسكو حيّة يمكنك اجتيازها، والوصول إليها بعبور النهر، وتصويرها في ضوء العصر نفسه الذي طارده مديرو التصوير. وللاطلاع على التاريخ الكامل وتنظيم الزيارة، راجع [دليلنا لآيت بن حدو](/ar/blog/ait-benhaddou-guide).

**كيف تزوره:** يقع آيت بن حدو على الطريق الرئيسي جنوبًا من مراكش. تتوقّف عنده تقريبًا كل جولات الصحراء — [جولتنا الصحراوية لأربعة أيام من مراكش](/ar/tours/desert-4day-marrakech) و[جولة الصحراء لثلاثة أيام](/ar/tours/sahara-3day-marrakech) تعبران كلتاهما ممرّ تيزي ن'تيشكا وتتوقّفان عند القصبة في الطريق إلى الكثبان.

## ورزازات واستوديوهات أطلس: هوليوود الصحراء

على بُعد خمس وعشرين دقيقة شرق آيت بن حدو تقع **ورزازات**، «باب الصحراء» — وعلى مشارفها **استوديوهات أطلس**، التي افتُتحت عام 1983 وتُوصف كثيرًا بأنها أكبر استوديو سينمائي في العالم من حيث المساحة. استعان أكثر من مئتي فيلم ومسلسل بورزازات واستوديوهاتها.

القائمة هنا استثنائية: **كوندون** (مارتن سكورسيزي، 1997)، و**المصارع**، و**المومياء**، و**مملكة السماء**، و**بابل**، و**بن هور**، و**سقوط الصقر الأسود**، و**آلام المسيح**، ومرة أخرى **صراع العروش**. تُحفظ ديكورات قائمة — دير تبتي ومعبد مصري ومدينة رومانية — في الساحة الخارجية للاستوديو وهي مفتوحة للزوّار، فتستطيع أن تمشي داخل المنشآت نفسها التي أطّرتها الكاميرات.

**كيف تزورها:** ورزازات محطة طبيعية للغداء أو المبيت على مسارات الصحراء الممتدّة لأيام. [جولة الأربعة أيام الصحراوية](/ar/tours/desert-4day-marrakech) نفسها تمرّ بها، وتُضاف زيارة الاستوديوهات بسهولة.

## الصويرة: أستابور على الأطلسي

على الساحل، حملت مدينة **الصويرة** العتيقة المسجَّلة لدى اليونسكو — ميناء محصَّن من القرن الثامن عشر صمّمه المهندس الفرنسي تيودور كورنو للسلطان محمد الثالث — صراع العروش إلى البحر. صارت أسوارها المرصوفة بالمدافع و**سقالة الميناء** مدينة **أستابور**، مدينة «اللامُدنَّسين»، في الموسم الثالث. صُوِّر «درب العقاب» على امتداد الأسوار البحرية التي يمكنك السير عليها مجانًا اليوم.

بل إن تاريخ الصويرة السينمائي أعرق: صوّر **أورسون ويلز** جزءًا كبيرًا من فيلمه **عطيل** هنا عامي 1949–1950 (ثمة ساحة تحمل اسمه)، وتظهر المدينة في **جون ويك: الفصل الثالث – باربيلوم** (2019).

**كيف تزورها:** الصويرة رحلة سهلة ليوم من الساحل — [رحلتنا من أكادير إلى الصويرة](/ar/tours/agadir-to-essaouira-day-trip) تجوب الأسوار والميناء والمدينة العتيقة حيث دارت الكاميرات.

## مدن التراث الأخرى

مواقع اليونسكو المتبقية في المغرب سينمائية بحدّ ذاتها حتى حيث ليست خلفيات شهيرة. فالمدن العتيقة في **فاس** (أول موقع مغربي يُسجَّل، عام 1981) و**مراكش** و**مكناس**، وأطلال **وليلي** الرومانية بأقواسها وفسيفسائها القائمة، والصهريج البرتغالي في **الجديدة** — الذي استخدمه أورسون ويلز في *عطيل* — تكافئ كلها المسافر الذي يأتي من أجل التاريخ ويبقى من أجل الأجواء.

## أن تقف حيث وقفت الكاميرات

ما يجعل المغرب فريدًا بين وجهات السينما أن الديكورات لم تكن يومًا ديكورات. آيت بن حدو، والصويرة، ووليلي — أماكن حقيقية محميّة مأهولة منذ ألف عام، صادف أنها مثالية أمام الكاميرا. أنت لا تزور نسخة معاد بناؤها؛ بل تزور الأصل، في الضوء نفسه، وعلى الحجر نفسه. ومعظمها يقع على امتداد المسارات الكلاسيكية جنوبًا وغربًا من مراكش، ولهذا فإن أسهل طريقة لرؤية سينما المغرب هي ببساطة أن تأخذ [جولة في صحراء الساهارا](/ar/tours/sahara-3day-marrakech) — إذ تأتي القصبات والاستوديوهات والكثبان رحلةً واحدة.
`,
