    content: `
## أسهل ملاذ من الساحل

من بين كل رحلات اليوم من أكادير، وادي الجنة هو الأشعر بالبُعد عن شريط المنتجعات مع كونه الأقرب للوصول. في نحو تسعين دقيقة تستبدل واجهة المحيط الأطلسي بأخدود نهري مليء بالنخيل في سفوح الأطلس الصغير — برك باردة، صخر أحمر، ولا فندق على مرمى البصر.

إليك كيف تصل فعلاً. لما تفعله عند الوصول، راجع [الدليل الكامل لوادي الجنة](/ar/blog/paradise-valley-agadir-complete-guide) و[دليل السباحة](/ar/blog/paradise-valley-swimming-guide).

## كم يبعد؟

يقع وادي الجنة على نحو **60 كم شمال شرق أكادير**، قرب قرية إموزار داء وتنان. احسب حوالي **ساعة ونصف** في كل اتجاه. ليست مسافة طويلة، لكن المقطع الأخير طريق جبلي متعرّج تسلكه ببطء — وهذا جزء من متعته، إذ ينفتح المنظر كلما صعدت.

## خياراتك

**بسيارة مستأجرة.** ممكن إن كنت مرتاحاً في قيادة المنعطفات الجبلية ولا تمانع البحث عن منطقة الركن والدرب نزولاً إلى البرك. انطلق باكراً لتفادي الحر والزحام معاً.

**بأجرة كبيرة (طاكسي كبير).** أرخص للمقعد لكن أقل مرونة، وستحتاج مع ذلك إلى تنظيم المشي ذهاباً وإياباً بتوقيتك الخاص.

**برحلة منظّمة.** الخيار الأبسط: نقل من الباب إلى الباب من أكادير، مرشد يأخذك إلى البرك الجيدة بدل أول بركة مزدحمة، ولا قيادة ولا توجّه تشغل بالك بهما. [رحلة يوم وادي الجنة وإموزار من أكادير](/ar/tours/paradise-valley-agadir) مصمّمة لهذا بالضبط.

## اجعله يوماً كاملاً

وادي الجنة من نصف يوم إلى يوم كامل بحسب مدة مكوثك في الماء. اذهب صباحاً — الضوء أفضل، والبرك أهدأ، وتتفادى أحرّ جزء من اليوم للمشي. ارتدِ لباس السباحة تحت ملابسك، واحمل أحذية مائية لقاع النهر الصخري وماءً وفيراً.

إن كان لديك أيام أكثر حول أكادير، يندمج الوادي جيداً مع رحلات أخرى: [درس ركمجة في أكادير](/ar/tours/agadir-surf-lesson) على الساحل، أو يوم إلى ميناء الصويرة الذي تعصف به الرياح مع [رحلتنا من أكادير إلى الصويرة](/ar/tours/agadir-to-essaouira-day-trip).

## مستعد للذهاب؟

👈 **[احجز رحلة يوم إلى وادي الجنة من أكادير](/ar/tours/paradise-valley-agadir)** — نقل ذهاباً وإياباً، مرشد محلي، ووقت للسباحة، كل ذلك مُنظَّم.
`,
