    content: `
## باب الصحراء

اعبر الأطلس الكبير جنوباً من مراكش يهبط الأخضر إلى المغرة والحجر. أول بلدة في جهة الصحراء هي **ورزازات** — المُلقَّبة «باب الصحراء»، وعلى نحو غير متوقَّع، من أكثر أماكن الأرض تصويراً. إن أخذت تقريباً أي جولة صحراوية من مراكش، فستعبرها، فيجدر أن تعرف ما تنظر إليه.

## لماذا يسمّونها «أواليوود»

ورزازات بديلة هوليوود للعالم القديم منذ أكثر من نصف قرن. **استوديوهات الأطلس** الضخمة على حافتها، مع القصبات والصحراء حولها، جسّدت مصر القديمة وروما والقدس والتبت وغيرها. القائمة سجلّ حقيقي: *لورانس العرب*، و*الرجل الذي أراد أن يكون ملكاً*، و*الإغراء الأخير للمسيح*، و*غلادييتور*، و*مملكة السماء*، و*المومياء*، و*بابل*، و*صراع العروش* — سارت دينيريس في خليج العبيد هنا.

ومن هنا **«أواليوود»**. يمكنك زيارة الاستوديوهات والتجوّل بين ديكورات قائمة: شوارع رومانية، ومعابد مصرية، وتماثيل فرعونية تُشوى في الشمس. إنها من قرب مزيّفة بمرح ووضوح، وأمتع لذلك. للقصة الأوسع للمغرب في السينما، راجع دليلنا لـ[مواقع التصوير المصنّفة تراثاً عالمياً في المغرب](/ar/blog/morocco-unesco-sites-film-locations).

## ماذا ترى فعلاً

- **استوديوهات الأطلس** (والأصغر CLA Studios): ديكورات السينما وأدواتها، سبب توقّف معظمهم.
- **قصبة تاوريرت**: قصبة طينية مرمّمة جميلة في البلدة، كانت مقرّ عائلة الكلاوي القوية؛ حقيقية لا ديكور.
- **آيت بن حدو**: الذروة، على نحو 30 دقيقة: القرية المحصّنة المصنّفة تراثاً عالمياً وهي بذاتها موقع تصوير دائم وأحد أجمل مشاهد المغرب. كل التفاصيل في [دليل آيت بن حدو](/ar/blog/ait-benhaddou-guide).
- **واحة فينت**: جيب أخضر أقل شهرةً قريب، انعطاف قصير جميل إن كان لديك وقت.

## كيف تندرج في رحلتك

كن واقعياً: ورزازات **توقّف ليلة رائع وباب، لا مدينة عدة أيام**. سحرها موقعها. تقع على نحو **4 ساعات من مراكش** عبر **ممر تيزي ن'تيشكا** البديع، حيث تسلّمك الجبال للصحراء بالضبط — وهو بالضبط سبب استخدام أطقم التصوير والجولات الصحراوية لها منصّة انطلاق.

في جولة صحراوية نمطية هي توقّف الليلة الأولى الطبيعي أو محطة غداء-واستوديوهات في الطريق إلى كثبان **زاكورة** أو **مرزوقة**. [جولتنا 3 أيام في الصحراء من مراكش](/ar/tours/sahara-3day-marrakech) و[مسار الصحراء من مراكش إلى فاس](/ar/tours/marrakech-to-fes-3day) يعبرانها كلاهما، فتحصل على ورزازات وآيت بن حدو منسوجتين في رحلة أكبر بدل رحلة منفصلة.

## الحُكم

لا تبنِ عطلة حول ورزازات — ابنِها حول الصحراء، ودع ورزازات تكون الباب المفعم بالطابع الذي تعبره، والكاميرا في يدك، في الطريق. بين ديكورات السينما والقصبات، إنها من أكثر التوقفات *متعةً* بحتة في طريق الجنوب.

👈 **[شاهد ورزازات وآيت بن حدو في جولة صحراوية](/ar/tours/sahara-3day-marrakech)**: استوديوهات السينما، والقصبات الكبرى، والكثبان خلفها، كلها في رحلة مع مرشدين يعرفون الحكايات خلف الديكورات.
`,
