    content: `
## الجواب المختصر

[جولة توبقال والصحراء في خمسة أيام](/ar/tours/toubkal-summit-sahara-5day) بـ
**635 يورو للفرد**، وتغطي نصفَي الرحلة من أولها إلى آخرها.

السؤال البديهي: ألا يمكن حجز رحلة توبقال وجولة الصحراء منفصلتين بأقل؟ يمكن حجزهما بأقل.
لكن لا يمكن *القيام بهما* بأقل — والفارق يوم ضائع.

## الحساب الذي يريده الجميع

| الخيار | السعر | ما الذي يحدث |
|---|---|---|
| [توبقال يومان](/ar/tours/toubkal-summit-2day-marrakech) + [الصحراء ثلاثة أيام](/ar/tours/sahara-3day-marrakech) | 418 يورو | عودة إلى مراكش بينهما؛ خمسة أيام زائد يوم انتقال |
| [المدمجة خمسة أيام](/ar/tours/toubkal-summit-sahara-5day) | 635 يورو | مسار متصل، سيارة خاصة، بلا عودة أدراج |

يبدو الحجز المنفصل أرخص بـ 217 يورو. وما يكلّفك إياه هو اليوم الفاصل بين الرحلتين —
تنزل من إمليل إلى مراكش، وتنام، ثم تنطلق جنوباً صباح اليوم التالي عبر طريق قطعت جزءاً
منه. أما المسار المدمج فيصل إمليل ← آيت بن حدو ← دادس ← عرق الشبي في خط واحد.

كما يستبدل الحافلة الصغيرة المشتركة بـ**سائق-مرشد خاص** في الجزء الصحراوي، وهو وحده
يفسّر معظم فارق السعر.

## أين تذهب الـ 635 يورو

| البند | التكلفة المعتادة 2026 | ملاحظات |
|---|---|---|
| مرشد جبال مرخّص (الرحلة الجبلية) | 500–800 درهم / يوم | يُقسَّم على المجموعة |
| سائق-مرشد خاص (الصحراء) | 800–1200 درهم / يوم | لكل سيارة، إنجليزي/فرنسي |
| ملجأ توبقال، نصف إقامة | 300–350 درهم / ليلة | الليلة 1، على 3207 م |
| دار ضيافة في إمليل | 200–300 درهم / ليلة | الليلة 2، بعد القمة |
| فندق في وادي دادس | 250–400 درهم / ليلة | الليلة 3، عشاء وفطور |
| مخيم صحراوي في عرق الشبي | 300–500 درهم / ليلة | الليلة 4، عشاء وفطور |
| بغل حمّال (الرحلة الجبلية) | 250–300 درهم / يوم | يحمل عتاد المجموعة |
| ركوب الجمال في عرق الشبي | مشمول | عند الغروب والشروق |
| رسوم منتزه توبقال + التنقلات | ثابت | الكل مشمول |

## الأيام الخمسة

- **اليوم 1** — مراكش ← إمليل ← ملجأ توبقال (3207 م)
- **اليوم 2** — قمة توبقال (4167 م)، ثم النزول إلى إمليل
- **اليوم 3** — إمليل ← آيت بن حدو ← وادي دادس
- **اليوم 4** — دادس ← مضايق تودغى ← مخيم عرق الشبي
- **اليوم 5** — شروق الشمس فوق الكثبان ← مراكش

اثنتان من أكبر تجارب المغرب دون يوم نقل ضائع بينهما.

## ما هو غير مشمول

- **تأمين السفر** — إلزامي للرحلة الجبلية
- **العتاد الشخصي للمشي وكيس النوم**
- **وجبات الغداء في أيام الصحراء** — احسب 12–15 يورو للوجبة
- **الكرامبونات وفأس الجليد** للصعود الشتوي (الكراء متاح في إمليل)
- **الإكراميات** للمرشدين والسائق والطباخ والمكاري

## هل هي الرحلة المناسبة؟

إن كان لديك خمسة أيام وتريد الجبل والصحراء معاً، فهذه هي الطريقة الفعّالة. وإن كانت
القمة وحدها تهمّك، فإن [رحلة توبقال في يومين](/ar/tours/toubkal-summit-2day-marrakech)
بـ 193 يورو تكفي. وإن كانت الكثبان هي الجذب، فإن
[جولة الصحراء في ثلاثة أيام](/ar/tours/sahara-3day-marrakech) بـ 225 يورو هي الطريق
المباشر.

يستحق الدمج فارقه حين تريد الاثنين فعلاً — لا كوسيلة للتوفير في أحدهما.

👉 **[اطّلع على جولة توبقال والصحراء في خمسة أيام](/ar/tours/toubkal-summit-sahara-5day)** — 635 يورو للفرد، قمة على 4167 متراً وليلة في كثبان عرق الشبي، خاصة من البداية إلى النهاية.
`,
